function studioReturnBar(current='Quotes'){return '<div class="qs-return-bar" style="'+studioVars()+'"><div class="qs-return-left"><button type="button" class="qs-return-home" data-qs-action="exit-quote-studio"><span>PB</span><b>Back to Pool Shed</b></button><div class="qs-breadcrumb"><span>Pool Shed</span><i>›</i><button type="button" data-qs-action="back-list">Quote Studio</button><i>›</i><strong>'+esc(current)+'</strong></div></div><div class="qs-return-actions">'+button('Quotes','back-list')+button('New quote','new-quote','primary')+'</div></div>'}
