function selectField(label,name,value,options){return '<div class="qs-field"><label>'+esc(label)+'</label><select name="'+esc(name)+'">'+options.map(o=>'<option value="'+esc(o.value)+'" '+(String(o.value)===String(value)?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></div>'}
