function statusTone(s){s=String(s||'').toLowerCase();return s.includes('accepted')||s.includes('won')?'good':s.includes('approval')||s.includes('pending')?'warn':s.includes('declin')||s.includes('cancel')?'bad':s.includes('sent')||s.includes('view')?'blue':''}
