function selectedBlock(){const s=selectedSection();return s&&(s.blocks||[]).find(b=>b.id===selectedBlockId)||null}
function quoteCompletion(qt){const checks=[!!qt.customerId,!!String(qt.projectName||'').trim(),(qt.sections||[]).some(s=>(s.options||[]).length>0),!!String(qt.presentation?.heroTitle||'').trim(),engine.validate(qt).errors.length===0];if(qt.workflow==='project')checks.push(!!qt.poolLayout?.shape);const done=checks.filter(Boolean).length;return {done,total:checks.length,pct:Math.round(done/checks.length*100)}}
function mediaList(qt){qt.mediaLibrary=Array.isArray(qt.mediaLibrary)?qt.mediaLibrary:[];return qt.mediaLibrary}
