 const left='<aside class="qs-builder-side left elite"><div class="qs-builder-nav"><button class="'+(builderPanel==='elements'?'active':'')+'" data-qs-builder-panel="elements">Elements</button><button class="'+(builderPanel==='products'?'active':'')+'" data-qs-builder-panel="products">Products</button><button class="'+(builderPanel==='sections'?'active':'')+'" data-qs-builder-panel="sections">Sections</button><button class="'+(builderPanel==='media'?'active':'')+'" data-qs-builder-panel="media">Uploads</button></div><div class="qs-builder-panel">'+panel+'</div></aside>';
 const blocks=(s?.blocks||[]).map(blockPreview).join('');const center='<main class="qs-canvas-stage elite device-'+esc(studioDevice)+'" style="--qs-canvas-scale:'+(studioZoom/100)+'"><div class="qs-canvas-toolbar"><div class="qs-canvas-toolbar-left"><span>LIVE CLIENT CANVAS</span><small>'+esc(s?.title||'Proposal section')+'</small></div><div class="qs-canvas-tools"><button type="button" class="'+(studioDevice==='desktop'?'active':'')+'" data-qs-action="canvas-desktop">Desktop</button><button type="button" class="'+(studioDevice==='tablet'?'active':'')+'" data-qs-action="canvas-tablet">Tablet</button><button type="button" class="'+(studioDevice==='mobile'?'active':'')+'" data-qs-action="canvas-mobile">Mobile</button><i></i><button type="button" data-qs-action="zoom-out">−</button><b>'+studioZoom+'%</b><button type="button" data-qs-action="zoom-in">+</button><i></i><button type="button" data-qs-action="toggle-builder-left">'+(studioLeftOpen?'Hide library':'Library')+'</button><button type="button" data-qs-action="toggle-builder-right">'+(studioRightOpen?'Hide inspector':'Inspector')+'</button><button type="button" class="focus" data-qs-action="focus-canvas">'+(studioFocusCanvas?'Exit focus':'Focus canvas')+'</button><button type="button" data-qs-action="preview">Preview</button></div></div><div class="qs-artboard-shell"><div class="qs-canvas"><header class="qs-canvas-head"><div><b>POOL BROS</b><small>Private client proposal</small></div><span>'+esc(qt.id)+'</span></header><div class="qs-canvas-body">'+(s?'<span class="eyebrow">'+esc(String(s.eyebrow||'YOUR CHOICES').toUpperCase())+'</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.intro||'')+'</p>'+blocks+'<div class="qs-client-options layout-'+esc(s.layout||'cards')+'" style="grid-template-columns:repeat('+Math.max(1,Number(s.style?.columns||3))+',minmax(0,1fr));gap:'+Number(s.style?.spacing||18)+'px">'+options.filter(x=>x.visible!==false).map(x=>canvasOption(x,s)).join('')+'</div>':'<div class="qs-empty"><h3>Add a section</h3></div>')+'</div></div></div></main>';
